      ? r.prospects.map((p) => String(p ?? '').trim()).filter(Boolean)
      : []
    if (many.length > 0) {
      for (const prospect of many) keeps.push({ briefKey: bk, prospect })
      continue
    }
    const prospect = String(r.prospect ?? '').trim()
    if (prospect) keeps.push({ briefKey: bk, prospect })
  }
}

