 */
export function expandIncrementSlots(
  single: unknown,
  many: unknown,
): Array<{ text: string; statusRaw?: unknown }> {
  const out: Array<{ text: string; statusRaw?: unknown }> = []
  if (Array.isArray(many)) {
    for (const x of many) {
      if (typeof x === 'string') {
        const t = x.trim()
        if (t) out.push({ text: t })
        continue
      }
      if (!x || typeof x !== 'object') continue
      const r = x as Record<string, unknown>
      const t = String(r.brief ?? r.prospect ?? r.text ?? '').trim()
      if (!t) continue
      out.push({
        text: t,
        statusRaw: r.status ?? r.readStatus,
      })
    }
    if (out.length > 0) return out
  }
  const one = String(single ?? '').trim()
  if (one) out.push({ text: one })
  return out
}

