/**
 * 意图空位导航：读台账缺哪类增量 → 找键 → 发指令（调哪工种 / 哪些 key）。
 * 权威流：无历史 peek→decide→infer→path；有历史 query(neighbour)→reuse(path)→…
 * 一次只推「当前最前空位」，不盲跑整条自动流。
 */

import {
  useAttentionIo,
  type DeskJob,
  type LetterDeskPackage,
} from './attentionIoStore'
import { listAllSettledBriefs, mapBriefToBook } from './masterTableMap'
import { listSettledQueryEntries } from './deskEntryGate'

export type GapKind =
  | 'brief'
  | 'neighbour'
  | 'reuse'
  | 'prospect'
  | 'infer'
  | 'path'
  | 'done'

export interface QueryGap {
  kind: GapKind
  /** 给人看的空位说明 */
  reason: string
  /** 写信台工种；reuse/done/path(等人) 可无 */
  job: DeskJob | null
  /** 建议调取的 briefKey（decide） */
  briefKeys: string[]
  /** 建议调取的 bookKey（peek/infer） */
  bookKeys: string[]
  /** 建议调取的 pathKey（reuse 展示） */
  pathKeys: string[]
  queryKey: string
}

function sid(): string {
  return `gap_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`
}

/** 本问已挂 brief；空则回落「库内全部 settled brief」（可供 decide 的材料池） */
function briefsForQuery(
  docId: string,
  queryKey: string,
  question: string,
): string[] {
  const s = useAttentionIo.getState()
  const fromQk = s.queryKeyToBriefKeys[queryKey] ?? []
  const fromQ = s.questionToBriefKeys[question] ?? []
  const merged = [...new Set([...fromQk, ...fromQ])]
  if (merged.length > 0) return merged
  return listAllSettledBriefs(docId).map((b) => b.briefKey)
}

/**
 * 按因果序找本问第一条空位。
 * 同问复用同一 queryKey 时：已齐的环跳过，只推还缺的环。
 */
export function inspectQueryGap(input: {
  docId: string
  queryKey: string
  question: string
}): QueryGap {
  const q = input.question.trim()
  const qk = input.queryKey.trim()
  const s = useAttentionIo.getState()

  const historicOthers = listSettledQueryEntries().filter(
    (e) => e.queryKey !== qk && e.qText.trim().length > 0,
  )
  const neighboursNow = s.neighbours.filter((n) => n.nowQueryKey === qk)
  const briefs = briefsForQuery(input.docId, qk, q)
  const prospects = s.prospects.filter((p) => p.queryKey === qk)
  const inferEdges = s.inferEdges.filter((e) => e.queryKey === qk)
  const paths = s.paths.filter((p) => p.queryKey === qk)
  const reuseLinks = s.queryReuseLinks.filter((l) => l.queryKey === qk)
  const pending = s.pendingPathMatch

  // ——— 有历史：先 neighbour，再 reuse ———
  if (historicOthers.length > 0) {
    if (neighboursNow.length === 0) {
      return {
        kind: 'neighbour',
        reason: `有历史问线×${historicOthers.length}，本问尚无 neighbour → 调 query`,
        job: 'query',
        briefKeys: [],
        bookKeys: [],
        pathKeys: [],
        queryKey: qk,
      }
    }
    const historicWithPath = new Set<string>()
    for (const n of neighboursNow) {
      const oldPaths = s.paths.filter(
        (p) => p.queryKey === n.historicQueryKey,
      )
      for (const p of oldPaths) historicWithPath.add(p.pathKey)
    }
    if (historicWithPath.size > 0 && reuseLinks.length === 0) {
      return {
        kind: 'reuse',
        reason: `neighbour 已指向含 path 的旧问，本问尚未 reuse → 走复用闸`,
        job: null,
        briefKeys: [],
        bookKeys: [],
        pathKeys: [...historicWithPath],
        queryKey: qk,
      }
    }
  }

  // ——— 无 brief 材料 → peek ———
  if (briefs.length === 0) {
    return {
      kind: 'brief',
      reason: '本问尚无 brief → 冷启/续 peek',
      job: 'peek',
      briefKeys: [],
      bookKeys: [],
      pathKeys: [],
      queryKey: qk,
    }
  }

  // ——— 有 brief、无本问 prospect → decide ———
  if (prospects.length === 0) {
    // 优先未读/不充分；无三态则全量 brief
    const unread = s.listKeysUnread('decide').filter((k) => briefs.includes(k))
    const weak = s.listKeysNeedingMore('decide').filter((k) =>
      briefs.includes(k),
    )
    const target =
      unread.length > 0 ? unread : weak.length > 0 ? weak : briefs
    return {
      kind: 'prospect',
      reason: `brief×${briefs.length} 已齐，本问尚无 prospect → 调 decide`,
      job: 'decide',
      briefKeys: target,
      bookKeys: [],
      pathKeys: [],
      queryKey: qk,
    }
  }

  // ——— 有 prospect、无 infer → infer ———
  if (inferEdges.length === 0) {
    const bookKeys: string[] = []
    for (const p of prospects) {
      const hit = mapBriefToBook(input.docId, p.briefKey)
      if (hit?.bookKey && !bookKeys.includes(hit.bookKey)) {
        bookKeys.push(hit.bookKey)
      }
    }
    if (bookKeys.length === 0) {
      for (const bk of briefs) {
        const hit = mapBriefToBook(input.docId, bk)
        if (hit?.bookKey && !bookKeys.includes(hit.bookKey)) {
          bookKeys.push(hit.bookKey)
        }
      }
    }
    return {
      kind: 'infer',
      reason: `prospect×${prospects.length} 已齐，本问尚无 infer → 调 infer`,
      job: 'infer',
      briefKeys: prospects.map((p) => p.briefKey),
      bookKeys,
      pathKeys: [],
      queryKey: qk,
    }
  }

  // ——— infer+prospect 有、无 path → 等人匹配 ———
  if (paths.length === 0) {
    const pendingNote =
      pending && pending.queryKey === qk
        ? '（已挂 pending）'
        : '（需人手匹配或跳过→监督）'
    return {
      kind: 'path',
      reason: `infer×${inferEdges.length} 与 prospect 已齐，尚无 path ${pendingNote}`,
      job: null,
      briefKeys: prospects.map((p) => p.briefKey),
      bookKeys: inferEdges.flatMap((e) => e.bookKeys),
      pathKeys: [],
      queryKey: qk,
    }
  }

  return {
    kind: 'done',
    reason: `本问账已齐：prospect×${prospects.length} · infer×${inferEdges.length} · path×${paths.length}` +
      (reuseLinks.length ? ` · reuse×${reuseLinks.length}` : ''),
    job: null,
    briefKeys: prospects.map((p) => p.briefKey),
    bookKeys: inferEdges.flatMap((e) => e.bookKeys),
    pathKeys: paths.map((p) => p.pathKey),
    queryKey: qk,
  }
}

/** 空位 → 写信台包（reuse 不在此建包，由调用方走 auto_flow） */
export function gapToDeskPackages(
  gap: QueryGap,
  question: string,
): LetterDeskPackage[] {
  if (!gap.job) return []
  const q = question.trim()
  const firstBrief = gap.briefKeys[0] || ''
  const firstBook = gap.bookKeys[0] || ''
  const pkg: LetterDeskPackage = {
    id: sid(),
    edgeId: `gap_${gap.kind}_${sid()}`,
    bookKey: firstBook,
    briefKey: firstBrief,
    question: q,
    job: gap.job,
    versionIndex: 0,
    createdAt: Date.now(),
    onlyBriefKeys:
      gap.job === 'decide' && gap.briefKeys.length > 0
        ? gap.briefKeys
        : undefined,
  }
  return [pkg]
}

input.new_string:
/**
 * 问题句 + 无钉住包 → 空位导航覆盖盲 auto_flow。
 * brief/reuse 仍走 auto_flow（需冷启 seal / 复用闸）；其余单步 dispatch。
 */
export function intentFromGap(gap: QueryGap, question: string): IntentAction {
  switch (gap.kind) {
    case 'brief':
    case 'reuse':
      return { type: 'auto_flow' }
    case 'neighbour':
    case 'prospect':
    case 'infer': {
      const packages = gapToDeskPackages(gap, question)
      if (packages.length === 0) return { type: 'auto_flow' }
      return { type: 'dispatch', packages }
    }
    case 'path':
      return {
        type: 'ask_user',
        prompt:
          `${gap.reason}。请在图上把 infer×prospect 配成 path，或说「跳过匹配」交给监督 LLM。`,
      }
    case 'done':
      return {
        type: 'show',
        prompt: `空位导航 · ${gap.reason}。同问已复用 queryKey=\`${gap.queryKey}\`；若某环不满意，请钉窗或说「重跑 decide/infer」。`,
      }
    default:
      return { type: 'auto_flow' }
  }
}

export async function runComposerTurn(input: {
  question: string
  bookIndex: BookIndex
  onProgress?: (msg: string) => void
  sealItems: Parameters<typeof runAutoFlow>[0]['sealItems']
}): Promise<{ ok: boolean; answer: string; note: string }> {
  const intro = detectIntroducedIo()
  const epoch = useAttentionIo.getState().intentSessionEpoch
  const q = input.question.trim()
  // 同问同键：先 ensure（复用或新铸），后续空位都挂这条 qk
  const turnQueryKey = q
    ? useAttentionIo.getState().ensureQueryKey(q)
    : ''

  let intent = heuristicIntent({ userText: input.question, intro })
  if (intent.type === 'ask_user' && q) {
    input.onProgress?.(
      `意图路由 · 轻量 LLM（会话 epoch=${epoch}）…`,
    )
    intent = await refineIntentWithLlm({
      userText: input.question,
      intro,
      heuristic: intent,
    })
  }

  // 空位导航：纯问题 + 未钉包 → 不盲跑整链，只推当前最前空位
  let gapNote = ''
  if (
    intro.kind === 'none' &&
    q &&
    turnQueryKey &&
    classifyUtterance(q) === 'question' &&
    (intent.type === 'auto_flow' || intent.type === 'ask_user')
  ) {
    const gap = inspectQueryGap({
      docId: input.bookIndex.docId,
      queryKey: turnQueryKey,
      question: q,
    })
    intent = intentFromGap(gap, q)
    gapNote = `gap=${gap.kind} · ${gap.reason}`
    input.onProgress?.(`空位导航 · ${gap.kind} · ${gap.reason}`)
  }

  useAttentionIo.getState().pushIntentDeskLog({
    question: input.question,
    action: intent.type,
    note:
      (gapNote ? `${gapNote} · ` : '') +
      (intent.type === 'ask_user'
        ? intent.prompt
        : intent.type === 'noop'
          ? intent.note
          : intent.type === 'show'
            ? intent.prompt
            : intent.type === 'dispatch'
              ? `dispatch×${intent.packages.length} · qk=${turnQueryKey}`
              : `auto_flow · qk=${turnQueryKey} · epoch=${epoch}`),
  })

  if (intent.type === 'ask_user') {
    useAttentionIo.getState().setDeskPrompt(`写信台 · ${intent.prompt}`)
    return { ok: false, answer: '', note: `ask_user · ${intent.prompt}` }
  }
  if (intent.type === 'noop') {
    return { ok: true, answer: '', note: intent.note }
  }
  if (intent.type === 'show') {
    useAttentionIo.getState().setDeskPrompt(`写信台 · ${intent.prompt}`)
    return { ok: true, answer: intent.prompt, note: `show · ${intent.prompt}` }
  }

  // 指令：跳过 path 匹配 → 监督 LLM
  if (
    /跳过匹配|监督匹配/.test(input.question) &&
    useAttentionIo.getState().pendingPathMatch
  ) {
    input.onProgress?.('写信台 · 用户跳过匹配 → 监督 LLM…')
    const { skipPendingPathMatchToSupervise } = await import(
      './letterDeskDispatch'
    )
    const r = await skipPendingPathMatchToSupervise({
      onProgress: input.onProgress,
    })
    return {
      ok: r.pathKeys.length > 0,
      answer: `### path 监督匹配\n${r.note}\npathKeys: ${r.pathKeys.map((k) => `\`${k}\``).join(', ')}`,
      note: r.note,
    }
  }

  if (intent.type === 'auto_flow') {
    return runAutoFlow({
      question: input.question,
      bookIndex: input.bookIndex,
      onProgress: input.onProgress,
      sealItems: input.sealItems,
    })
  }

  // dispatch（空位单步或显式指令）
  const packages = intent.packages.map((p) => ({
    ...p,
    question: p.question.trim() || q,
  }))
  return askDeepSeekWithLetterDesk({
    question: q,
    packages,
    bookIndex: input.bookIndex,
    docId: input.bookIndex.docId,
    turnQueryKey: turnQueryKey || undefined,
    onProgress: input.onProgress,
  })
}

