/**
 * 问题句 + 无钉住包 → 空位导航覆盖盲 auto_flow。
 * brief/reuse 仍走 auto_flow（需冷启 seal / 复用闸）；其余单步 dispatch。
 */
export function intentFromGap(gap: QueryGap, question: string): IntentAction {
  switch (gap.kind) {
    case 'brief':
    case 'reuse':
      return { type: 'auto_flow' }
    case 'neighbour':
    case 'prospect':
    case 'infer': {
      const packages = gapToDeskPackages(gap, question)
      if (packages.length === 0) return { type: 'auto_flow' }
      return { type: 'dispatch', packages }
    }
    case 'path':
      return {
        type: 'ask_user',
        prompt:
          `${gap.reason}。请在图上把 infer×prospect 配成 path，或说「跳过匹配」交给监督 LLM。`,
      }
    case 'done':
      return {
        type: 'show',
        prompt: `空位导航 · ${gap.reason}。同问已复用 queryKey=\`${gap.queryKey}\`；若某环不满意，请钉窗或说「重跑 decide/infer」。`,
      }
    default:
      return { type: 'auto_flow' }
  }
}

